code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Enclosed rectangular outlines are filled according to their cavity size.
    for r0 in range(h):
        for r1 in range(r0 + 2, h):
            for c0 in range(w):
                for c1 in range(c0 + 2, w):
                    color = grid[r0][c0]
                    if color == grid[r0][c1] == grid[r1][c0] == grid[r1][c1]:
                        if all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0,c1+1)) and all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0,r1+1)):
                            interior = [grid[r][c] for r in range(r0+1,r1) for c in range(c0+1,c1)]
                            if interior and len(set(interior)) == 1 and interior[0] != color:
                                fill = 7 if len(interior) <= 9 else 2
                                for r in range(r0+1,r1):
                                    for c in range(c0+1,c1): out[r][c] = fill
    return out
'''
